/* yuexin_cat_frames.c - YuexinCat 跳舞 396 帧资源 (56x56, 30 fps).
 *
 * 编码格式 V24 (体积优化, 画面逐位不变):
 *   帧 0 为原始位图; 帧 1..395 是 XOR 增量 (Elias-gamma 间隔 + 8 位新值)。
 *   增量位流不再直接存储, 而是用静态上下文算术编码 (LZMA range coder,
 *   8 位概率) 压缩: 每帧一个独立码块, offsets[] 给出码块的字节起点,
 *   因此任何一帧都能 O(1) 定位、独立解码 (倒放/乒乓不需要额外状态)。
 *   概率表 g_ycat_m_lead / g_ycat_m_suf / g_ycat_m_val 由 tools/gen_ycat.py
 *   对三段动画的增量流统计得到, 解码器只做查表。
 * 体积: frame0 392 B + offsets 794 B + counts 396 B + stream 32881 B
 *       + 概率表 2158 B = 36621 B (旧格式 43057 B, 省 6436 B)。
 * 全部 const => 只占 Flash。由 tools/gen_ycat.py 生成, 请勿手改。
 */
